def compute(vars):
    net_income = vars["Net Income"]
    sales_revenue = vars["Sales Revenue"]
    total_assets = vars["Total Assets"]

    try:
        profit_margin = net_income / sales_revenue
        asset_turnover = sales_revenue / total_assets
        return_on_assets = profit_margin * asset_turnover
    except ZeroDivisionError:
        return None

    return {
        "value": return_on_assets,
        "trace": {
            "Net Income": net_income,
            "Sales Revenue": sales_revenue,
            "Total Assets": total_assets,
            "profit_margin": profit_margin,
            "asset_turnover": asset_turnover,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
